const fs = require('fs');
const src = fs.readFileSync('/home/zmhel/gitrepos/learn-ai/eval01/runs/.gen-work/t23/game.html', 'utf8');
const m = src.match(/<script>([\s\S]*)<\/script>/);
const el = () => ({
  innerHTML: '', style: {}, value: '',
  classList: { add() {}, remove() {} }, addEventListener() {},
  focus() {}, select() {}, offsetWidth: 0, offsetHeight: 0,
  setAttribute() {}, getAttribute() { return null; }, hasAttribute() { return false; },
  getBoundingClientRect: () => ({ left: 0, bottom: 0 })
});
global.document = { addEventListener() {}, getElementById: el, currentScript: null };
global.window = { innerWidth: 1000, innerHeight: 800 };
let code = m[1];
code += '\nglobal.__api={runTests,runBench,newGame,greedyTurn,alive,scoreOf,stateHash,serialize,deserialize,S};';
try { (0, eval)(code); } catch (e) {
  console.log('EVAL ERROR:', e.message);
  console.log(e.stack.split('\n').slice(0, 6).join('\n'));
  process.exit(1);
}
const A = global.__api;
const t = A.runTests();
console.log('TESTS: pass=' + t.pass + ' fail=' + t.fail);
t.lines.forEach(l => { if (l.startsWith('FAIL')) console.log('  ' + l); });
const b1 = A.runBench(1337, 200), b2 = A.runBench(1337, 200);
console.log('BENCH hash', b1.hash, '==', b2.hash, b1.hash === b2.hash ? 'OK' : 'MISMATCH');
console.log('  pop', b1.pop, 'peak', b1.peakPop, 'res', b1.research, 'bld', b1.buildings, 'morale', b1.avgMorale, 'score', b1.score);
console.log('  resources', JSON.stringify(b1.res));

// playability probe: greedy over 60 turns on several seeds
for (const s of [1337, 7, 99, 2024, 555]) {
  const g = A.newGame(s);
  for (let i = 0; i < 60 && !g.over; i++) A.greedyTurn(g);
  console.log('seed', s, 'turn', g.turn, 'pop', A.alive(g), 'win', g.win, 'score', g.score || A.scoreOf(g).total,
    'food', g.r.food.toFixed(1), 'water', g.r.water.toFixed(1), 'res', g.res_done.length);
}

