tool_input.content:
// TEMPORARY verification harness for game.html - deleted after use.
const fs = require('fs');
const src = fs.readFileSync(__dirname + '/t23/game.html', 'utf8');
const m = src.match(/<script>([\s\S]*)<\/script>/);
const el = () => ({
  innerHTML: '', style: {}, value: '',
  classList: { add() {}, remove() {} }, addEventListener() {},
  focus() {}, select() {}, offsetWidth: 0, offsetHeight: 0,
  setAttribute() {}, getAttribute() { return null; }, hasAttribute() { return false; },
  getBoundingClientRect: () => ({ left: 0, bottom: 0 })
});
global.document = { addEventListener() {}, getElementById: el, currentScript: null };
global.window = { innerWidth: 1000, innerHeight: 800 };
let code = m[1];
code += '\nglobal.__api={runTests,runBench,newGame,greedyTurn,alive,scoreOf,forecast,render,renderMap,renderPeople,renderResearch,renderTrade,renderLog,renderDev,serialize,deserialize,stateHash,UI};';
try { (0, eval)(code); } catch (e) {
  console.log('EVAL ERROR:', e.message);
  console.log(e.stack.split('\n').slice(0, 8).join('\n'));
  process.exit(1);
}
const A = global.__api;

const t = A.runTests();
console.log('TESTS: pass=' + t.pass + ' fail=' + t.fail);
t.lines.forEach(l => { if (l.indexOf('FAIL') === 0) console.log('  ' + l); });

const b1 = A.runBench(1337, 200), b2 = A.runBench(1337, 200);
console.log('BENCH', b1.hash, b1.hash === b2.hash ? 'DETERMINISTIC' : 'MISMATCH ' + b2.hash);
console.log('  pop', b1.pop, 'peak', b1.peakPop, 'research', b1.research, 'bld', b1.buildings,
  'morale', b1.avgMorale, 'score', b1.score);
console.log('  resources', JSON.stringify(b1.res));

for (const s of [1337, 7, 99, 2024, 555, 31337]) {
  const g = A.newGame(s);
  for (let i = 0; i < 60 && !g.over; i++) A.greedyTurn(g);
  console.log('seed', s, '| turn', g.turn, '| pop', A.alive(g), '| win', g.win, '| score', g.score,
    '| food', g.r.food.toFixed(1), '| water', g.r.water.toFixed(1), '| research', g.res_done.length,
    '| morale', Math.round(g.people.reduce((a, p) => a + p.mor, 0) / (g.people.length || 1)));
}

// render smoke test: every tab must produce markup without throwing
try {
  for (const fn of ['renderMap', 'renderPeople', 'renderResearch', 'renderTrade', 'renderLog', 'renderDev']) {
    const out = A[fn]();
    if (typeof out !== 'string' || out.length < 20) throw new Error(fn + ' produced nothing');
  }
  console.log('RENDER: all six tabs render');
} catch (e) { console.log('RENDER ERROR:', e.message); }
